import XCTest
@testable import FlagshipCore

/// Pins the Swift port to packages/protocol/test-vectors/org-authority/vectors.json (generated by
/// tools/org-authority-vectors.ts): canonical forms, SAS, member seeds, every chain, seat-book and
/// predicate case.
final class OrgAuthorityVectorTests: XCTestCase {
    private var V: [String: Any] = [:]

    override func setUpWithError() throws {
        var dir = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        for _ in 0..<14 {
            let url = dir.appendingPathComponent("packages/protocol/test-vectors/org-authority/vectors.json")
            if FileManager.default.fileExists(atPath: url.path) {
                V = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
                return
            }
            dir = dir.deletingLastPathComponent()
        }
        throw XCTSkip("org-authority vectors not found above \(#filePath)")
    }

    private func resolve(_ v: Any?) -> Any? {
        if let a = v as? [Any] { return a.map { resolve($0) as Any } }
        guard let o = v as? [String: Any] else { return v }
        if let k = o["$key"] as? String { return ((V["keys"] as! [String: Any])[k] as! [String: Any])["binding"] }
        if let i = o["$approval"] as? NSNumber { return (V["approvals"] as! [Any])[i.intValue] }
        return o.mapValues { resolve($0) as Any }
    }

    private func i64(_ v: Any?) -> Int64 { (v as! NSNumber).int64Value }
    private func code(_ f: () throws -> Void) -> String {
        do { try f(); return "ok" } catch let e as OrgAuthorityError { return e.code } catch { return "other: \(error)" }
    }
    private func expected(_ c: [String: Any]) -> String {
        let e = c["expect"] as! [String: Any]
        return (e["ok"] as! Bool) ? "ok" : e["code"] as! String
    }

    private func chain(_ c: [String: Any], upTo: Int? = nil) throws -> OrgAuthorityState {
        var entries = try (c["entries"] as! [Any]).map { try OrgAuthorityWire.entry($0) }
        if let n = upTo { entries = Array(entries.prefix(n)) }
        return try OrgAuthority.verifyChain(entries, genesisHash: (c["genesisHash"] as? String) ?? V["genesisHash"] as! String, now: i64(c["now"]),
                                            freezes: try ((c["freezes"] as? [Any]) ?? []).map { try OrgAuthorityWire.freeze($0) },
                                            overturns: try ((c["overturns"] as? [Any]) ?? []).map { try OrgAuthorityWire.overturn($0) },
                                            vetoes: try ((c["vetoes"] as? [Any]) ?? []).map { try OrgAuthorityWire.veto($0) })
    }

    func testCanonicalSasAndSeeds() throws {
        for c in V["canonical"] as! [[String: Any]] {
            XCTAssertEqual(OrgAuthority.sha256Hex(Array((c["bytes"] as! String).utf8)), c["sha256"] as? String, c["name"] as! String)
        }
        let s = V["sas"] as! [String: Any]
        XCTAssertEqual(try OrgAuthority.seatSas(inviteSha256: s["inviteSha256"] as! String, memberKeyId: s["memberKeyId"] as! String,
                                                adminKeyId: s["adminKeyId"] as! String), s["code"] as? String)
        let m = V["memberSeeds"] as! [String: Any]
        let seeds = try OrgAuthority.memberSeeds(umk: PqBin.unhex(m["umkHex"] as! String)!, orgId: m["orgId"] as! String)
        XCTAssertEqual(PqBin.hex(seeds.edSeed), m["edSeedHex"] as? String)
        XCTAssertEqual(PqBin.hex(seeds.mldsaSeed), m["mldsaSeedHex"] as? String)
        let roles = try OrgAuthorityWire.roles([["role": "server-admin", "servers": ["home.acme.flagship.services"]], ["role": "service-admin", "apps": ["acme--wiki"]]])
        let scoped = (V["canonical"] as! [[String: Any]]).first { $0["name"] as? String == "roles scoped" }!
        XCTAssertEqual(String(decoding: try OrgAuthority.canonicalRoles(roles), as: UTF8.self), scoped["bytes"] as? String)
    }

    func testChains() throws {
        for raw in V["chains"] as! [Any] {
            let c = resolve(raw) as! [String: Any]
            var state: OrgAuthorityState?
            let got = code { state = try chain(c) }
            XCTAssertEqual(got, expected(c), c["name"] as! String)
            if got == "ok" { XCTAssertEqual(state?.current.version, i64(c["currentVersion"]), c["name"] as! String) }
        }
    }

    private func base() throws -> OrgAuthorityState {
        try chain(resolve((V["chains"] as! [Any])[0]) as! [String: Any], upTo: 2)
    }

    private func book(_ raw: Any, _ st: OrgAuthorityState) throws -> OrgSeatBook {
        let c = resolve(raw) as! [String: Any]
        let now = i64(((V["chains"] as! [Any])[0] as! [String: Any])["now"])
        return OrgAuthority.buildSeatBook(st, grants: try (c["grants"] as! [Any]).map { try OrgAuthorityWire.grantBundle($0) },
                                          revokes: try (c["revokes"] as! [Any]).map { try OrgAuthorityWire.revokeBundle($0) }, now: now)
    }

    func testSeatBooks() throws {
        let st = try base()
        for raw in V["seatBooks"] as! [Any] {
            let c = raw as! [String: Any], name = c["name"] as! String
            let b = try book(raw, st)
            XCTAssertEqual(b.seats.keys.sorted(), (c["expectSeats"] as! [String]).sorted(), name)
            let refused = (c["expectRefused"] as! [[String: Any]]).map { "\($0["seatId"]!):\($0["code"]!)" }
            XCTAssertEqual(b.refused.map { "\($0.seatId):\($0.code)" }, refused, name)
        }
    }

    func testAuthorize() throws {
        let st = try base()
        let b = try book((V["seatBooks"] as! [Any])[0], st)
        for raw in V["authorize"] as! [Any] {
            let c = resolve(raw) as! [String: Any], name = c["name"] as! String
            var scoped: String??
            let got = code {
                let r = try OrgAuthority.authorize(state: st, book: b, action: try OrgAuthorityWire.action(c["action"]),
                                                   order: Array((c["order"] as! String).utf8),
                                                   approvals: try OrgAuthorityWire.approvals(c["approvals"]), now: i64(c["now"]))
                scoped = .some(r.scopedSeat)
            }
            XCTAssertEqual(got, expected(c), name)
            if got == "ok" { XCTAssertEqual(scoped!, (c["expect"] as! [String: Any])["scopedSeat"] as? String, name) }
        }
    }
}
